  'room.cocina.desc': 'التغذية: سجّل الوجبات والمغذّيات الكبرى والماء وخطتك الأسبوعية.',
  'room.ejercicio.desc': 'روتينات القوة والتحمل والمرونة مع أهداف.',
  'room.recamara.desc': 'تتبّع راحتك واكتب دفتر ذكرياتك الشخصي.',
  'room.descanso.desc': 'نومك كسماء ليلية: جدول، منبّه، تقييم وسجل الليالي.',
  'room.anecdotario.desc': 'دفتر ذكرياتك الشخصي: ذكريات مع الصور والمزاج اليومي.',
  'room.despacho.desc':
    'المالية: ميزانية بالمصروفات والدخل (الثابت والمتغير)، أهداف (حاسبات مالية، الادخار والاستثمار، الديون) مع محاكيات، وأسواق مباشرة.',
  'room.biblioteca.desc': 'موسوعة تفاعلية: محادثات مع الذكاء الاصطناعي، مقالات ويكي وجلسات دراسة.',
  'room.entretenimiento.desc': 'أرشيف الأفلام والمسلسلات والكتب وألعاب الطاولة.',
  'room.sala.desc': 'خطط لرحلاتك: المسار، المصروفات، قائمة التحقق وقائمة الأمنيات.',
  'room.jardin.desc': 'الهدوء: تأملات موجّهة، تمارين تنفس ودفتر الامتنان.',
  'room.garage.desc': 'صيانة مركباتك وخدماتها.',
  'room.diario.desc': 'مركز الأخبار اليومية حسب الفئة.',
  'room.hobbies.desc': 'هواياتك ومشاريعك الإبداعية.',
  'room.idiomas.desc': 'تعلّم اللغات: معلّم بالذكاء الاصطناعي، مفردات بالتكرار المتباعد، منهج حسب المستوى وتمارين.',
  'room.calendario.desc': 'تقويمك: الأحداث والروتينات حسب اليوم والأسبوع والشهر.',
  'room.caminos.desc': 'ارسم مضامير السباق وسكك القطارات والأفعوانيات على الخريطة.',
  'room.canchas.desc': 'ضع ملاعب كرة القدم والتنس وكرة السلة والبيسبول على الخريطة.',
  'room.huerto.desc': 'جهّز الأحواض وازرع المحاصيل واسقها واحصدها في الوقت الفعلي.',
  'room.granja.desc': 'ربِّ الدجاج والخنازير والماعز والأغنام والأبقار والخيول وازرع علفها في المحرر نفسه.',
  'room.ideas.desc':
    'دفتر أفكارك وعصف ذهنك، عشرة أشكال لخرائط المفاهيم على لوحة حرة (خريطة ذهنية، شجرة، خط زمني، دورة، هرم، فن…) وثمانية مخططات لاتخاذ القرار (الإيجابيات والسلبيات، حقل القوى، سوات، مصفوفة أيزنهاور، شجرة القرار، قائمة الترتيب، مصفوفة القرار الموزونة وإيشيكاوا)، يدويًا أو بالذكاء الاصطناعي.',
  'room.metas.desc':
    'ما عزمت عليه، من كل أنحاء البيت: قائمة الأهداف بأهدافها الفرعية وخطواتها، والخطط التي يقترحها الذكاء الاصطناعي لكل هدف (مراحل بتاريخ تتحول إلى أهداف فرعية حقيقية)، والجدول الزمني حيث يأخذ كل شيء فترته على المحور الزمني.',
  'room.computo.desc':
    'غرفة الحاسوب: آلة حاسبة علمية معلَّق بها كتيب صيغك (رياضيات وفيزياء وكيمياء جاهزة وقابلة للتعديل) وثمانية أنماط — راسم بياني بأربعة أنواع (ثنائي الأبعاد، قطبي، بارامتري وسطح ثلاثي الأبعاد)، ثنائي وسداسي عشري، مصفوفات، أنظمة معادلات، تحويل الوحدات، الإكرامية وقاعدة الثلاثة؛ وجداول بيانات تُصدَّر إلى إكسل وPDF.',
