  'ideas.guia.matriz':
    'كل معيار يزن بقدر أهميته لك (1-5)، وكل خيار يُقيَّم فيه من 1 إلى 5. المجموع يضرب الدرجة في الوزن، فلا يفوز شيء لمجرد أنه ممتاز في أمر لا يهمك.',
  'ideas.matriz.criterio': 'معيار',
